// Vendors xterm's dist JS + CSS into a TypeScript module.
//
// The terminal renders inside a WebView, which has no access to node_modules and
// no network (the page is loaded from an inline HTML string, so every asset it
// needs must already be in that string). Embedding the library is therefore not
// an optimization — it is the only way the page can have an emulator at all.
//
// JSON.stringify does the escaping: xterm's minified source contains backticks
// and `${`, which a template literal would interpret.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const out = resolve(root, 'src/components/terminal/xterm-bundle.ts');

const js = readFileSync(resolve(root, 'node_modules/@xterm/xterm/lib/xterm.js'), 'utf8');
const css = readFileSync(resolve(root, 'node_modules/@xterm/xterm/css/xterm.css'), 'utf8');

mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// GENERATED by scripts/generate-xterm-bundle.mjs — do not edit.
// Re-run \`npm run xterm:bundle\` after upgrading @xterm/xterm.
/* eslint-disable */
export const XTERM_JS = ${JSON.stringify(js)};
export const XTERM_CSS = ${JSON.stringify(css)};
`
);
console.log(`wrote ${out} (${(js.length / 1024).toFixed(0)} KB js, ${(css.length / 1024).toFixed(0)} KB css)`);
